"""Measure exact on-policy update from a delayed wave under two waiting-state caps."""
from contextlib import nullcontext
from dataclasses import dataclass
import json
from pathlib import Path
import statistics
import sys
from time import perf_counter
import weakref

import torch
from torch.multiprocessing.reductions import StorageWeakRef
from transformers import AutoModelForCausalLM, AutoTokenizer

from retained_graph import live_graph
from tail_replay import (
    CONSOLE, Episode, REVISION, RankOne, cached_scores, capture, digest, draw,
    gradients, prompts,
)


JOBS, BATCH, STEPS = 8, 4, 16
SEEDS = (3817, 3818, 3819)
DEVICE_CAP, HOST_CAP = 2 * 1024**2, 1024**3
MODES = ("full", "tail_device", "tail_host", "graph_device", "graph_host")


@dataclass
class Job:
    episode: Episode
    scores: torch.Tensor | None


class PinnedGraph:
    """Save each dynamic storage once and preserve the saved tensor's exact view."""
    def __init__(self, model):
        self.static = {
            tensor.untyped_storage().data_ptr()
            for tensor in (*model.parameters(), *model.buffers()) if tensor.is_cuda
        }
        self.copies = {}
        self.host_refs = []

    def hooks(self):
        return torch.autograd.graph.saved_tensors_hooks(self.pack, self.unpack)

    @staticmethod
    def byte_view(tensor):
        storage = tensor.untyped_storage()
        return torch.empty(0, device=tensor.device, dtype=torch.uint8).set_(
            storage, 0, (storage.nbytes(),), (1,)
        )

    def pack(self, tensor):
        storage = tensor.untyped_storage()
        if not tensor.is_cuda or storage.data_ptr() in self.static:
            return (None, tensor.detach())
        key = storage.data_ptr()
        entry = self.copies.get(key)
        pinned = None if entry is None or entry[0].expired() else entry[1]()
        if pinned is None:
            pinned = pin(self.byte_view(tensor.detach()))
            reference = weakref.ref(pinned)
            self.copies[key] = StorageWeakRef(storage), reference
            self.host_refs.append(reference)
        return tensor.device, pinned, tensor.dtype, tensor.size(), tensor.stride(), tensor.storage_offset()

    @staticmethod
    def unpack(packed):
        device, host, *view = packed
        if device is None:
            return host
        dtype, size, stride, offset = view
        storage = host.to(device, non_blocking=True).untyped_storage()
        return torch.empty(0, device=device, dtype=dtype).set_(storage, offset, size, stride)

    def live_host_bytes(self):
        return sum(t.untyped_storage().nbytes() for reference in self.host_refs
                   if (t := reference()) is not None)


def pin(tensor):
    target = torch.empty_like(tensor, device="cpu", pin_memory=True)
    return target.copy_(tensor, non_blocking=True)


def collect(model, prompt, uniforms, eos, mode, offload):
    if mode.startswith("graph"):
        with offload.hooks() if offload is not None else nullcontext():
            episode, scores = live_graph(model, prompt, uniforms, eos)
        return Job(episode, scores)
    episode = capture(model, prompt, uniforms, eos, save=mode.startswith("tail"))
    if mode == "tail_host":
        episode.saved = pin(episode.saved)
    return Job(episode, None)


def update_snapshot(parameters, summed, jobs):
    copied = [torch.nn.Parameter(p.detach().clone()) for p in parameters]
    optimizer = torch.optim.AdamW(copied, lr=0.003, weight_decay=0.0)
    for parameter, grad in zip(copied, summed, strict=True):
        parameter.grad = grad / jobs
    optimizer.step()
    return copied, tuple(optimizer.state[p][k] for p in copied for k in ("step", "exp_avg", "exp_avg_sq"))


def host_bytes(jobs, offload):
    if offload is not None:
        return offload.live_host_bytes()
    return sum(j.episode.saved.untyped_storage().nbytes() for j in jobs
               if j.episode.saved is not None and j.episode.saved.device.type == "cpu")


def digest_job(job):
    ep = job.episode
    return [digest(value) for value in (ep.actions, ep.support, ep.behavior, ep.indices)]


def arm(model, prompt, uniforms, eos, feedbacks, mode, params, *, device_cap=DEVICE_CAP):
    queue, admissions, raw = [], [], []
    offload = PinnedGraph(model) if mode == "graph_host" else None
    torch.cuda.synchronize()
    baseline = torch.cuda.memory_allocated()
    torch.cuda.reset_peak_memory_stats()
    start = perf_counter()
    for draws in uniforms:
        queue.append(collect(model, prompt, draws, eos, mode, offload))
        torch.cuda.synchronize()
        allocation = torch.cuda.memory_allocated() - baseline
        host = host_bytes(queue, offload)
        accepted = allocation <= device_cap and host <= HOST_CAP
        admissions.append({"device_bytes": allocation, "host_bytes": host, "accepted": accepted})
        if not accepted:
            break
    arrival = perf_counter()
    completed = len(admissions) == len(uniforms) and admissions[-1]["accepted"]
    if completed:
        summed = [torch.zeros_like(param) for param in params]
        for job, feedback in zip(queue, feedbacks, strict=True):
            episode, scores = job.episode, job.scores
            if mode == "tail_host":
                episode.saved = episode.saved.to("cuda", non_blocking=True)
            if scores is None:
                scores = cached_scores(model, episode, tail=mode.startswith("tail"))
            grad = gradients(scores, episode, feedback, params)
            raw.append((scores.detach(), grad))
            for acc, item in zip(summed, grad, strict=True):
                acc.add_(item)
            if mode == "tail_host":
                episode.saved = None
            job.scores = None
        updated, state = update_snapshot(params, summed, len(queue))
    torch.cuda.synchronize()
    end = perf_counter()
    row = {
        "admissions": admissions, "completed": completed,
        "collect_ms": (arrival - start) * 1000, "feedback_ms": (end - arrival) * 1000,
        "total_ms": (end - start) * 1000,
        "max_incremental_peak_bytes": torch.cuda.max_memory_allocated() - baseline,
        "trajectory_hashes": [digest_job(job) for job in queue],
    }
    if completed:
        row.update({
            "all_behavior_logits_bitwise": all(
                torch.equal(job.episode.behavior, logits) for job, (logits, _) in zip(queue, raw, strict=True)
            ),
            "per_job_gradient_sha256": [[digest(g) for g in gs] for _, gs in raw],
            "sum_gradient_sha256": [digest(g) for g in summed],
            "adam_parameter_sha256": [digest(p) for p in updated],
            "adam_state_sha256": [digest(t) for t in state],
        })
    return row


def summarize(records):
    summary = {}
    for mode in MODES:
        arms = [record["arms"][mode] for record in records]
        exact = all(row["exact"] for row in arms)
        summary[mode] = {
            "all_exact": exact,
            "completed_queues": sum(row["completed"] for row in arms),
            "max_accepted_before_feedback": max(sum(a["accepted"] for a in row["admissions"]) for row in arms),
            "median_total_ms": statistics.median(row["total_ms"] for row in arms) if exact else None,
            "median_feedback_ms": statistics.median(row["feedback_ms"] for row in arms) if exact else None,
            "max_device_bytes_at_admission": max(a["device_bytes"] for row in arms for a in row["admissions"]),
            "max_host_bytes_at_admission": max(a["host_bytes"] for row in arms for a in row["admissions"]),
        }
    controls = [summary[mode]["median_total_ms"] for mode in ("full", "graph_device", "graph_host")
                if summary[mode]["all_exact"]]
    valid = summary["full"]["all_exact"]
    tail = summary["tail_host"]["median_total_ms"]
    return summary, valid and tail is not None and tail <= 0.80 * min(controls)


def main():
    torch.set_num_threads(1)
    torch.set_float32_matmul_precision("highest")
    checkpoint, output, log = map(Path, sys.argv[1:])
    tokenizer = AutoTokenizer.from_pretrained(checkpoint, local_files_only=True, trust_remote_code=False)
    model = AutoModelForCausalLM.from_pretrained(
        checkpoint, dtype=torch.bfloat16, attn_implementation="sdpa", use_safetensors=True,
        local_files_only=True, trust_remote_code=False,
    ).to("cuda").eval()
    model.requires_grad_(False)
    assert model.config.num_hidden_layers == 28 and not model.model.has_sliding_layers
    rng = torch.Generator(device="cuda").manual_seed(92017)
    attention = model.model.layers[-1].self_attn
    attention.q_proj = RankOne(attention.q_proj, rng)
    attention.v_proj = RankOne(attention.v_proj, rng)
    params = attention.q_proj.input, attention.q_proj.output, attention.v_proj.input, attention.v_proj.output
    assert {id(p) for p in params} == {id(p) for p in model.parameters() if p.requires_grad}
    eos_ids = model.generation_config.eos_token_id
    eos = torch.tensor(eos_ids if isinstance(eos_ids, list) else [eos_ids], device="cuda")
    prompt = prompts(tokenizer, BATCH)
    coefficients = [torch.linspace(-0.75, 0.95, BATCH, dtype=torch.float32, device="cuda") + i / 32
                    for i in range(JOBS)]
    warm = [draw(BATCH, 3, 899)]
    for mode in MODES:
        arm(model, prompt, warm, eos, coefficients[:1], mode, params, device_cap=2**30)
    records = []
    keys = ("trajectory_hashes", "per_job_gradient_sha256", "sum_gradient_sha256",
            "adam_parameter_sha256", "adam_state_sha256")
    with log.open("x", encoding="utf-8") as journal:
        for turn, seed in enumerate(SEEDS):
            randoms = [draw(BATCH, STEPS, seed * 100 + job) for job in range(JOBS)]
            order = MODES[turn:] + MODES[:turn]
            rows = {mode: arm(model, prompt, randoms, eos, coefficients, mode, params) for mode in order}
            reference = rows["full"]
            assert reference["completed"] and reference["all_behavior_logits_bitwise"]
            for row in rows.values():
                anchors = row["trajectory_hashes"]
                row["sampled_prefix_matches"] = anchors == reference["trajectory_hashes"][:len(anchors)]
                row["exact"] = row["completed"] and row["all_behavior_logits_bitwise"] and all(
                    row[key] == reference[key] for key in keys
                )
            record = {"seed": seed, "order": order, "arms": rows}
            records.append(record)
            journal.write(json.dumps(record, sort_keys=True, allow_nan=False) + "\n")
            journal.flush()
            CONSOLE.print_json(data={"seed": seed, "round": summarize([record])[0]})
    summary, passes = summarize(records)
    result = {"model_revision": REVISION, "device": torch.cuda.get_device_name(), "device_cap": DEVICE_CAP,
              "host_cap": HOST_CAP, "jobs": JOBS, "batch": BATCH, "steps": STEPS,
              "records": records, "summary": summary, "passes": passes}
    CONSOLE.print_json(data={"summary": summary, "passes": passes})
    with output.open("x", encoding="utf-8") as stream:
        json.dump(result, stream, allow_nan=False, sort_keys=True)


if __name__ == "__main__":
    main()
